import { createAdabiLesson } from "../shared.js";

export const source = ":::exam-question\nid: it-t-p027-q01\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 1\nquestion: كم عدد الخانات الثنائية التي يتكون منها كل من IPv4 و IPv6؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 1\nanswer-label: إجابة نموذجية للتدريب\nbody:\nكم عدد الخانات الثنائية التي يتكون منها كل من IPv4 و IPv6؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n- يتكوّن عنوان IPv4 من 32 بت.\n- يتكوّن عنوان IPv6 من 128 بت.\nsolution:\n- **IPv4:** يتكوّن من **32 بت**.\n- **IPv6:** يتكوّن من **128 بت**.\n\nفي IPv4 توجد أربع خانات، في كل منها 8 بتات؛ لذلك:\n\n$$4 \\times 8 = 32$$\n\nيوضح الكتاب بنية IPv4 في ص12 (PDF14). أما طول IPv6 فيأتي استكمالًا لفقرة البحث في الرزمة ص14 (PDF16)، وتؤكده [مواصفة IPv6، RFC8200](https://www.rfc-editor.org/rfc/rfc8200.html#section-1).\n:::\n\n:::exam-question\nid: it-t-p027-q02\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 2\nquestion: كيف يتم التمييز بين جزء عنوان الشبكة وجزء الجهاز في عنوان الـ IP؟ دعم إجابتك بأمثلة.\nreference: الكتاب · ص 25 · PDF 27 · السؤال 2\nanswer-label: إجابة نموذجية للتدريب\nbody:\nكيف يتم التمييز بين جزء عنوان الشبكة وجزء الجهاز في عنوان الـ IP؟ دعم إجابتك بأمثلة.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nيفصل قناع الشبكة بين جزء الشبكة وجزء الجهاز.\n\n- في العنوان `192.168.3.2` مع القناع `255.255.255.0`، جزء الشبكة هو `192.168.3` وجزء الجهاز `2`، وتكتب الشبكة بصيغة CIDR هكذا `192.168.3.0/24`.\n- في العنوان `192.168.4.25` مع القناع `255.255.0.0`، جزء الشبكة هو `192.168` وجزء الجهاز `4.25`، وتكتب الشبكة بصيغة CIDR هكذا `192.168.0.0/16`.\nsolution:\nالقناع يحدد مواضع جزء الشبكة ومواضع جزء الجهاز. في الأمثلة التي مقاطع قناعها 255 أو 0، تحفظ المقاطع المقابلة لـ255 في جزء الشبكة، وتكون المقاطع المقابلة للصفر جزء الجهاز.\n\n- `192.168.3.2` مع `255.255.255.0`: أول ثلاثة مقاطع للشبكة، والأخير للجهاز. جزء الشبكة `192.168.3` والجهاز `2`؛ وعنوان الشبكة الكامل `192.168.3.0/24`.\n- `192.168.4.25` مع `255.255.0.0`: أول مقطعين للشبكة وآخر مقطعين للجهاز. جزء الشبكة `192.168` والجهاز `4.25`؛ وعنوان الشبكة الكامل `192.168.0.0/16`.\n\nالصفر في عنوان الشبكة الكامل يملأ مواضع الجهاز؛ فلا نخلط بين «جزء الشبكة» و«عنوان الشبكة» الكامل. الكتاب، ص 12–13، 22 (صفحات PDF 14–15، 24).\n:::\n\n:::exam-question\nid: it-t-p027-q03\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 3\nquestion: خلال مسار الرسالة بين المرسل والمستقبل ما هي العناوين التي تبقى ثابتة داخل الرسالة؟ وما هي العناوين التي تتغير بالانتقال من موجه لآخر؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 3\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nخلال مسار الرسالة بين المرسل والمستقبل ما هي العناوين التي تبقى ثابتة داخل الرسالة؟ وما هي العناوين التي تتغير بالانتقال من موجه لآخر؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n- في التوجيه العادي تبقى عناوين IP للمصدر والوجهة ثابتة بين الجهازين.\n- أما عناوين MAC في الإطار فتتغير من وصلة إلى أخرى عند كل موجه، وفق واجهة الإرسال والوجهة التالية.\nsolution:\nنميز بين **عنواني طرفي الرحلة** و**عنواني الوصلة الحالية**:\n\n- **IP المصدر وIP الوجهة:** يبقيهما التوجيه العادي ثابتين لأن الحزمة تنتقل بين الجهازين نفسيهما.\n- **MAC المصدر وMAC الهدف:** يتغيران عند الانتقال من وصلة إلى أخرى. ينشئ الموجه إطارًا جديدًا للوصلة التالية، ويضع فيه عنوان واجهة الإرسال وعنوان الطرف التالي.\n\nإذن ثبات وجهة الحزمة لا يعني ثبات عنوان هدف الإطار طوال المسار.\n\nالكتاب، ص 21–24 (صفحات PDF 23–26).\n:::\n\n:::exam-question\nid: it-t-p027-q04\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 4\nquestion: ما الفرق بين العنوان المنطقي والعنوان الفيزيائي؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 4\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nما الفرق بين العنوان المنطقي والعنوان الفيزيائي؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n- **العنوان الفيزيائي (MAC):** يرتبط بواجهة الشبكة ويستخدم لإرسال الإطارات داخل الوصلة المحلية.\n- **العنوان المنطقي (IP):** يحدد الجهاز وشبكته منطقيًا ويستخدم لتوجيه الحزم بين الشبكات، وقد يتغير عند تغيير الشبكة.\nsolution:\nنقارن **وظيفة العنوان** ونطاق استخدامه:\n\n- **MAC الفيزيائي:** يميز واجهة الشبكة على الوصلة المحلية، ويستخدمه المحوّل لتحويل الإطار.\n- **IP المنطقي:** يحدد الجهاز وشبكته منطقيًا، ويستخدمه الموجه لتوجيه الحزم بين الشبكات.\n\nلهذا قد يتغير IP عند تغيير الشبكة، بينما يبقى MAC الأصلي مرتبطًا بالبطاقة نفسها في نموذج الكتاب.\n\nالكتاب، ص 3–4، 11–12 (صفحات PDF 5–6، 13–14).\n:::\n\n:::exam-question\nid: it-t-p027-q05\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 5\nquestion: ما الجهاز الذي يتم استخدامه لتوجيه الرسائل بين الأجهزة التي تنتمي لشبكات مختلفة؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 5\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nما الجهاز الذي يتم استخدامه لتوجيه الرسائل بين الأجهزة التي تنتمي لشبكات مختلفة؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nالموجّه (Router).\nsolution:\nيقول الكتاب:\n\n> من أهم أجهزة الشبكة التي تعمل في الطبقة الثالثة (طبقة الشبكة) **جهاز الموجه Router**\n\nالكتاب، ص 20 (صفحة PDF 22).\n\nالمطلوب الربط بين **شبكات مختلفة**؛ وهذه هي وظيفة الموجه في طبقة الشبكة.\n:::\n\n:::exam-question\nid: it-t-p027-q06\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 6\nquestion: أي عنوان داخل الرسالة يستخدمه الموجه لأخذ القرار إلى أي منفذ يجب توجيه الرسالة؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 6\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nأي عنوان داخل الرسالة يستخدمه الموجه لأخذ القرار إلى أي منفذ يجب توجيه الرسالة؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nيستخدم الموجّه عنوان IP للوجهة، ويبحث عن مسار شبكتها في جدول التوجيه لاختيار المنفذ أو الموجّه التالي.\nsolution:\nقرار الموجه يتعلق **بوجهة الحزمة**. نتتبع الخطوات:\n\n1. يقرأ الموجه **IP الوجهة** من الحزمة.\n2. يبحث عن شبكة الوجهة في جدول التوجيه.\n3. يختار منفذ الخروج أو الموجه التالي.\n\nأما MAC فيخص توصيل الإطار على الوصلة الحالية؛ لذلك لا يكفي لاختيار مسار الحزمة بين الشبكات.\n\nالكتاب، ص 23–24 (صفحات PDF 25–26).\n:::\n\n:::mcq\nid: it-t-p028-q02\ntitle: الكتاب · ص 26 · PDF 28 · السؤال 1-2\nkicker: الكتاب · ص 26 · PDF 28 · السؤال 1-2\nreference: الكتاب · ص 26 · PDF 28 · السؤال 1-2\nquestion: أي العناوين الآتية يستخدمه الموجه router لتوجيه الحزمة بين الشبكات؟\n- [ ] option-1 | Email address.\n- [x] option-2 | IP address.\n- [ ] option-3 | Port address.\n- [ ] option-4 | Mac address.\nexplanation:\nالسؤال عن **حزمة بين شبكات مختلفة**، لذلك يقرأ الموجه عنوان **IP الوجهة** ليحدد شبكة الوصول ومسارها. أما MAC فيتغير عند الانتقال من وصلة إلى أخرى ولا يحدد المسار الكامل.\n\nالكتاب، ص 20–24 (صفحات PDF 22–26).\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### أسئلة الوحدة\n:::\n\n:::mcq\nid: it-t-p028-q03\ntitle: الكتاب · ص 26 · PDF 28 · السؤال 1-3\nkicker: الكتاب · ص 26 · PDF 28 · السؤال 1-3\nreference: الكتاب · ص 26 · PDF 28 · السؤال 1-3\nquestion: أي الأوامر الآتية يستخدم لتتبع مسار رسالة من المصدر إلى الهدف؟\n- [ ] option-1 | ipconfig.\n- [ ] option-2 | ping.\n- [x] option-3 | tracert.\n- [ ] option-4 | Ipconfig /all.\nexplanation:\nيقول الكتاب:\n\n> كتابة الأمر **tracert www.google.com** على موجه سطر الأوامر.\n\nالكتاب، ص20 (صفحة PDF22).\n\nكلمة **«تتبع المسار»** تقابل الأمر `tracert`؛ إذ يعرض خطوات الوصول إلى الوجهة.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### أسئلة الوحدة\n:::\n\n:::mcq\nid: it-t-p028-q04\ntitle: الكتاب · ص 26 · PDF 28 · السؤال 1-4\nkicker: الكتاب · ص 26 · PDF 28 · السؤال 1-4\nreference: الكتاب · ص 26 · PDF 28 · السؤال 1-4\nquestion: أي خيار في واجهة إعداد الموجّه يعرض قائمة الأجهزة التي حصلت على عناوين من خدمة DHCP؟\n- [ ] option-1 | DHCP Settings\n- [ ] option-2 | DHCP Client\n- [x] option-3 | DHCP Client List\n- [ ] option-4 | DMZ\nexplanation:\nالمطلوب **قائمة الأجهزة التي حصلت على عناوين**، لا إعداد الخدمة نفسها. لذلك نختار **DHCP Client List**: كلمة Client للأجهزة الزبونة وList للقائمة. أما DHCP Settings فلتعديل إعدادات التوزيع.\n\nالكتاب، ص 16 (صفحة PDF 18).\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### أسئلة الوحدة\n:::\n\n:::exam-question\nid: it-t-p028-q05\ntitle: الكتاب · ص 26 · PDF 28 · السؤال 2\nquestion: ما الفرق بين نظام العنونة الفيزيائي ونظام العنونة المنطقي؟ وفي أي طبقات في نموذج الـ OSI توجد هذه الأنظمة؟\nreference: الكتاب · ص 26 · PDF 28 · السؤال 2\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nما الفرق بين نظام العنونة الفيزيائي ونظام العنونة المنطقي؟ وفي أي طبقات في نموذج الـ OSI توجد هذه الأنظمة؟\n\n### أسئلة الوحدة\nfinal-answer:\n| نظام العنونة | الغرض | طبقة OSI |\n|---|---|---|\n| فيزيائي (MAC) | إيصال الإطارات على الوصلة المحلية | ربط البيانات (الطبقة الثانية) |\n| منطقي (IP) | تحديد الشبكة والجهاز وتوجيه الحزم بين الشبكات | الشبكة (الطبقة الثالثة) |\nsolution:\nنربط كل نظام عنونة بوحدة البيانات التي يخدمها:\n\n| النظام | الطبقة | الوظيفة |\n|---|---|---|\n| MAC الفيزيائي | ربط البيانات، الثانية | تحويل الإطار على الوصلة المحلية |\n| IP المنطقي | الشبكة، الثالثة | تحديد الشبكة والجهاز وتوجيه الحزم بين الشبكات |\n\nثبات عنوان MAC على البطاقة لا يجعله بديلًا من IP؛ لكل منهما نطاق عمل مختلف. الكتاب، ص 3–4، 11–12 (صفحات PDF 5–6، 13–14).\n:::\n\n:::exam-question\nid: it-t-p029-q03\ntitle: الكتاب · ص 27 · PDF 29 · السؤال 6\nquestion: كم عنوان IPv4 مختلفًا يمكن إنشاؤه؟\nreference: الكتاب · ص 27 · PDF 29 · السؤال 6\nanswer-label: إجابة نموذجية للتدريب\nbody:\nكم عنوان IPv4 مختلفًا يمكن إنشاؤه؟\n\n### أسئلة الوحدة\nfinal-answer:\nتوجد 2³² قيمة ثنائية ممكنة نظريًا، أي 4,294,967,296 قيمة. تُحجز بعض القيم لاستخدامات خاصة.\nsolution:\nعنوان IPv4 طوله **32 بت**. لكل موضع خياران مستقلان، لذا عدد القيم:\n\n$$2^{32}=4294967296$$\n\nهذا عدد العناوين النظري الكلي، وليس عدد عناوين الأجهزة العامة المتاحة؛ بعض المجالات محجوز لاستخدامات خاصة. الكتاب، ص 12–13 (صفحات PDF 14–15).\n:::\n\n:::exam-question\nid: it-t-p029-q04\ntitle: الكتاب · ص 27 · PDF 29 · السؤال 7\nquestion: ما الهدف من استخدام الأمر ipconfig /all؟\nreference: الكتاب · ص 27 · PDF 29 · السؤال 7\nanswer-label: إجابة نموذجية للتدريب\nbody:\nما الهدف من استخدام الأمر ipconfig /all؟\n\n### أسئلة الوحدة\nfinal-answer:\nيعرض الأمر ipconfig /all في ويندوز تفاصيل إعداد الشبكة لكل واجهة، مثل عناوين IP وMAC، وقناع الشبكة، والبوابة الافتراضية، وخوادم DNS وDHCP عند توفرها.\nsolution:\nيطلب الجزء **`/all`** عرض التفاصيل الموسعة لواجهات الشبكة. لذلك يعرض الأمر **`ipconfig /all`** معلومات مثل:\n\n- العنوان الفيزيائي **MAC** وعنوان **IPv4**.\n- قناع الشبكة والبوابة الافتراضية.\n- خوادم DNS وإعداد DHCP عند توفره.\n\nالأمر يعرض الإعدادات ولا يغيّر العنوان. أما **`ipconfig`** فيكفي لعرض إعدادات IP الأساسية.\n\nالكتاب، ص 18–19 (صفحات PDF 20–21).\n:::\n\n:::exam-question\nid: it-t-p029-q05\ntitle: الكتاب · ص 27 · PDF 29 · السؤال 8\nquestion: علل ما يلي:\nreference: الكتاب · ص 27 · PDF 29 · السؤال 8\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nعلل ما يلي:\n\n### أسئلة الوحدة\n\n- أ. عدم اختلاف عنوان الـ MAC لجهاز الحاسوب رغم انتقاله من شبكة إلى أخرى.\n- ب. استحداث نظام عنونة IP جديد IPv6.\nfinal-answer:\n- أ. عنوان MAC الأصلي مرتبط بواجهة الشبكة المستخدمة، وتغيير الشبكة لا يغيّر الواجهة نفسها.\n- ب. عدد عناوين IPv4 محدود ولا يواكب نمو الأجهزة المتصلة، لذلك أُنشئ IPv6 لتوفير فضاء عنونة أوسع.\nsolution:\n**أ. ثبات MAC:** الانتقال بين الشبكات لا يبدّل بطاقة الشبكة نفسها، والعنوان الأصلي مرتبط بالبطاقة التي أعطاها المصنّع إياه.\n\n**ب. استحداث IPv6:** طول IPv4 البالغ 32 بت يحد فضاءه بـ $2^{32}$ قيمة. ازدياد الأجهزة جعل هذا الفضاء غير كافٍ؛ يرفع IPv6 الطول إلى 128 بت، فيوفر $2^{128}$ قيمة نظرية.\n\nالكتاب، ص4،12،14 (صفحات PDF6،14،16). طول IPv6 موثق في [RFC8200](https://www.rfc-editor.org/rfc/rfc8200.html#section-1).\n:::\n\n:::mcq\nid: it-e-p046-q01\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-1 · 2019 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-1 · 2019 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-1 · 2019 — الدورة الأولى\nquestion: أي من الأوامر الآتية يستخدم لفحص الاتصال مع عنوان IP على الشبكة؟\n- [ ] option-1 | Ipconfig\n- [ ] option-2 | Ipconfig/all\n- [x] option-3 | Ping\n- [ ] option-4 | Tracert\nexplanation:\nيقول الكتاب:\n\n> يستخدم أمر **ping** في موجه الأوامر لفحص الاتصال مع عنوان IP على الشبكة.\n\nالكتاب، ص 19\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q02\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-2 · 2019 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-2 · 2019 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-2 · 2019 — الدورة الأولى\nquestion: كم عنوانًا موجودًا في شبكة قناعها (255.255.0.0)؟\n- [ ] option-1 | 2²\n- [ ] option-2 | 2⁴\n- [ ] option-3 | 2⁸\n- [x] option-4 | 2¹⁶\nexplanation:\nالقناع **`255.255.0.0`** يخصص أول خانتين للشبكة، ويترك آخر خانتين للجهاز. كل خانة تضم 8 بتات، إذن:\n\n$$2 \\times 8 = 16$$\n\nلكل بت احتمالان، فيكون مجموع العناوين:\n\n$$2^{16}=65536$$\n\nإذن العدد **65,536 عنوانًا** وفق عدّ العناوين في الكتاب. المطلوب مجموع العناوين، وليس عدد عناوين المضيفين القابلة للتخصيص بعد حجز عنواني الشبكة والبث.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q03\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-3 · 2019 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-3 · 2019 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-3 · 2019 — الدورة الثانية\nquestion: كم عنوانًا موجودًا في شبكة قناعها (255.255.255.0)؟\n- [ ] option-1 | 64\n- [ ] option-2 | 128\n- [ ] option-3 | 255\n- [x] option-4 | 256\nexplanation:\nالقناع **`255.255.255.0`** يخصص أول ثلاث خانات للشبكة، ويترك خانة واحدة للجهاز. تضم هذه الخانة **8 بتات**، ولكل بت احتمالان؛ لذلك:\n\n$$2^8=256$$\n\nإذن مجموع العناوين **256**. المطلوب مجموع العناوين كما يعدّها الكتاب، فلا نطرح عنواني الشبكة والبث.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q04\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-4 · 2019 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-4 · 2019 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-4 · 2019 — الدورة الثانية\nquestion: أي من العناوين الآتية يستخدمه الموجه (Router) لتوجيه الحزمة بين الشبكات؟\n- [ ] option-1 | Port Address\n- [ ] option-2 | Mac Address\n- [x] option-3 | IP Address\n- [ ] option-4 | Email Address\nexplanation:\nيقول الكتاب:\n\n> يقوم الموجه بتحويل الرسالة بين الشبكات اعتمادًا على **عنوان IP** الموجود في الرسالة (الحزمة) وصولا للهدف.\n\nالكتاب، ص 21\n\nالموجه يحتاج معرفة **الوجهة التي ستصل إليها الحزمة**، لذلك يعتمد على **IP الهدف**.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q05\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-5 · 2019 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-5 · 2019 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-5 · 2019 — الدورة الثانية\nquestion: أي من الأوامر الآتية يستخدم لتتبع مسار رسالة من المصدر إلى الهدف؟\n- [ ] option-1 | Ipconfig\n- [ ] option-2 | Ipconfig/all\n- [ ] option-3 | Ping\n- [x] option-4 | Tracert\nexplanation:\nيقول الكتاب:\n\n> كتابة الأمر **tracert** www.google.com على موجه سطر الأوامر.\n\nالكتاب، ص 20\n\nهذا الأمر يعرض خطوات المسار إلى الوجهة، ولذلك يُستخدم لتتبّع الموجهات التي تمر بها الرسالة.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q06\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-6 · 2019 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-6 · 2019 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-6 · 2019 — الدورة الثانية\nquestion: كم عدد خانات عنوان IPv4؟\n- [x] option-1 | 4\n- [ ] option-2 | 16\n- [ ] option-3 | 32\n- [ ] option-4 | 255\nexplanation:\nيقول الكتاب:\n\n> يتكون عنوان الـ IPv4 من 32 بت يقسم إلى **4 خانات**، في كل خانة 8 بت.\n\nالكتاب، ص 12\n\nالسؤال عن **الخانات الأربع في طريقة العرض**، لا عن البتات؛ فالعنوان كله يتكون من **32 بتًا**.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q07\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-7 · 2019 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-7 · 2019 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-7 · 2019 — الدورة الثالثة\nquestion: يطلق على تنسيق الرسالة في طبقة الشبكة عند انتقال الرسالة من المرسل إلى المستقبل؟\n- [ ] option-1 | إطار Frame\n- [ ] option-2 | بيانات Data\n- [ ] option-3 | قطعة Segment\n- [x] option-4 | حزمة Packet\nexplanation:\nيقول الكتاب:\n\n> يسمى تنسيق الرسالة في هذه الطبقة ب**حزمة (Packet)**.\n\nالكتاب، ص 11\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q08\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-8 · 2019 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-8 · 2019 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-8 · 2019 — الدورة الثالثة\nquestion: يقوم الموجه بتحويل الرسالة بين الشبكات وصولًا للمستقبل اعتمادًا على عنوان:\n- [x] option-1 | IP للهدف\n- [ ] option-2 | MAC للهدف\n- [ ] option-3 | IP المصدر\n- [ ] option-4 | MAC للمصدر\nexplanation:\nيقول الكتاب:\n\n> يقوم الموجه بتحويل الرسالة بين الشبكات اعتمادًا على **عنوان IP** الموجود في الرسالة (الحزمة) وصولا للهدف.\n\nالكتاب، ص 21\n\nالموجه يحتاج معرفة **الوجهة التي ستصل إليها الحزمة**، لذلك يعتمد على **IP الهدف**.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q09\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-9 · 2019 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-9 · 2019 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-9 · 2019 — الدورة الثالثة\nquestion: عدد العناوين التي يدعمها بروتوكول IPv4 هو:\n- [ ] option-1 | 2⁸\n- [ ] option-2 | 2¹⁶\n- [ ] option-3 | 2²⁴\n- [x] option-4 | 2³²\nexplanation:\nيتكون IPv4 من **32 بت**، ولكل بت قيمتان محتملتان. نعد جميع التركيبات بالرفع إلى القوة:\n\n$$2^{32}=4294967296$$\n\nإذن العدد الكلي **4,294,967,296 عنوانًا**. الخانات العشرية الأربع هي طريقة عرض العنوان؛ أما **32** فهو عدد خاناته الثنائية.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q10\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-10 · 2019 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-10 · 2019 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-10 · 2019 — الدورة الثالثة\nquestion: كم عنوانًا موجودًا في شبكة قناعها (255.255.255.0)؟\n- [x] option-1 | 2⁸\n- [ ] option-2 | 2¹⁶\n- [ ] option-3 | 2²⁴\n- [ ] option-4 | 2³²\nexplanation:\nالقناع **`255.255.255.0`** يخصص أول ثلاث خانات للشبكة، ويترك خانة واحدة للجهاز. تضم هذه الخانة **8 بتات**، ولكل بت احتمالان؛ لذلك:\n\n$$2^8=256$$\n\nإذن مجموع العناوين **256**. المطلوب مجموع العناوين كما يعدّها الكتاب، فلا نطرح عنواني الشبكة والبث.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q11\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-11 · 2019 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-11 · 2019 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-11 · 2019 — الدورة الثالثة\nquestion: يستخدم من أجل التمييز بين الجزء الخاص بعنوان الجهاز والجزء الخاص بعنوان الشبكة:\n- [x] option-1 | Subnet mask\n- [ ] option-2 | MAC Address\n- [ ] option-3 | TCP/IP\n- [ ] option-4 | HTTP\nexplanation:\nيقول الكتاب:\n\n> قناع الشبكة subnet mask: حيث إن قناع الشبكة مكون من 4 خانات تماما كعنوان الـ IPv4، ويتم استخدام هذا القناع من أجل **التمييز بين الجزء الخاص بعنوان الجهاز والجزء الخاص بعنوان الشبكة**.\n\nالكتاب، ص 12\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q12\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-12 · 2020 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-12 · 2020 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-12 · 2020 — الدورة الأولى\nquestion: ما الأمر المستخدم لفحص الاتصال مع عنوان IP على الشبكة؟\n- [ ] option-1 | tracert\n- [ ] option-2 | cmd\n- [ ] option-3 | ipconfig\n- [x] option-4 | ping\nexplanation:\nيقول الكتاب:\n\n> يستخدم أمر **ping** في موجه الأوامر لفحص الاتصال مع عنوان IP على الشبكة.\n\nالكتاب، ص 19\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q13\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-13 · 2020 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-13 · 2020 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-13 · 2020 — الدورة الأولى\nquestion: ما البروتوكول الذي يقوم بتوزيع العناوين بشكل تلقائي على أجهزة الشبكة؟\n- [ ] option-1 | TCP/IP\n- [ ] option-2 | PPP\n- [x] option-3 | DHCP\n- [ ] option-4 | HTTP\nexplanation:\nيقوم **DHCP** بتوزيع عناوين IP تلقائيًا من مجموعة متاحة لديه على أجهزة الشبكة التي تطلب الخدمة، بدل تكوين عنوان كل جهاز يدويًا. لذلك يقابل وصف «توزيع العناوين تلقائيًا» هذا البروتوكول. الكتاب، ص 14.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q14\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-14 · 2020 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-14 · 2020 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-14 · 2020 — الدورة الأولى\nquestion: ما الطبقة التي تقوم بتوجيه الرسالة من المصدر للهدف عبر الموجهات؟\n- [ ] option-1 | طبقة ربط البيانات\n- [x] option-2 | طبقة الشبكة\n- [ ] option-3 | طبقة النقل\n- [ ] option-4 | الطبقة الفيزيائية\nexplanation:\nيقول الكتاب:\n\n> من المهام الأخرى لهذه الطبقة **توجيه الرسالة (الحزمة) من المصدر للهدف عبر الموجهات** Routers، حيث يقوم الموجه بتوجيه الرسالة عبر أقصر الطرق اعتمادًا على عنوان IP الهدف الموجود في رأس الحزمة.\n\nالكتاب، ص 11\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p046-q15\ntitle: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-15 · 2020 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-15 · 2020 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 46 · PDF 46 · السؤال 1-15 · 2020 — الدورة الثانية\nquestion: ما الأمر المستخدم لمعرفة كم موجه يقوم بتوجيه الرسالة وصولًا لموقع ما على شبكة الإنترنت؟\n- [x] option-1 | tracert\n- [ ] option-2 | cmd\n- [ ] option-3 | ipconfig\n- [ ] option-4 | ping\nexplanation:\nيقول الكتاب:\n\n> كتابة الأمر **tracert** www.google.com على موجه سطر الأوامر.\n\nالكتاب، ص 20\n\nهذا الأمر يعرض خطوات المسار إلى الوجهة، ولذلك يُستخدم لتتبّع الموجهات التي تمر بها الرسالة.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p047-q01\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-16 · 2020 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-16 · 2020 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-16 · 2020 — الدورة الثانية\nquestion: ماذا يسمى تنسيق الرسالة في طبقة الشبكة؟\n- [ ] option-1 | إطار\n- [x] option-2 | حزمة\n- [ ] option-3 | قطعة\n- [ ] option-4 | بت\nexplanation:\nيقول الكتاب:\n\n> يسمى تنسيق الرسالة في هذه الطبقة ب**حزمة (Packet)**.\n\nالكتاب، ص 11\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p047-q02\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-17 · 2020 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-17 · 2020 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-17 · 2020 — الدورة الثالثة\nquestion: ما العنوان الذي يعتمد عليه الموجه (ROUTER) عندما يقوم بتحويل الرسالة بين الشبكات وصولًا للمستقبل؟\n- [x] option-1 | IP للهدف\n- [ ] option-2 | MAC للمصدر\n- [ ] option-3 | IP للمصدر\n- [ ] option-4 | MAC للهدف\nexplanation:\nيقول الكتاب:\n\n> يقوم الموجه بتحويل الرسالة بين الشبكات اعتمادًا على **عنوان IP** الموجود في الرسالة (الحزمة) وصولا للهدف.\n\nالكتاب، ص 21\n\nالموجه يحتاج معرفة **الوجهة التي ستصل إليها الحزمة**، لذلك يعتمد على **IP الهدف**.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p047-q03\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-18 · 2021 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-18 · 2021 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-18 · 2021 — الدورة الأولى\nquestion: أي من الأوامر الآتية يستخدم لتتبع مسار رسالة من المصدر إلى الهدف؟\n- [x] option-1 | tracert\n- [ ] option-2 | DNS\n- [ ] option-3 | ipconfig\n- [ ] option-4 | ping\nexplanation:\nيقول الكتاب:\n\n> كتابة الأمر **tracert** www.google.com على موجه سطر الأوامر.\n\nالكتاب، ص 20\n\nهذا الأمر يعرض خطوات المسار إلى الوجهة، ولذلك يُستخدم لتتبّع الموجهات التي تمر بها الرسالة.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p047-q04\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-19 · 2021 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-19 · 2021 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-19 · 2021 — الدورة الأولى\nquestion: أي من التالية يمكن اعتبارها عنوان IP صحيح (IPv4)؟\n- [ ] option-1 | 192.861.200.1\n- [ ] option-2 | A1.34.1.861\n- [x] option-3 | 200.12.30.77\n- [ ] option-4 | 192.268.2.5\nexplanation:\nنفحص شرطين لعنوان IPv4 المكتوب بالنظام العشري:\n\n1. يتكون من **أربع خانات عددية**.\n2. تكون قيمة كل خانة عددًا صحيحًا من **0 إلى 255**.\n\nالعنوان **`200.12.30.77`** يحقق الشرطين. أما **861** و**268** فتتجاوزان الحد، و**A1** ليست خانة مكتوبة بالنظام العشري.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p047-q05\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-20 · 2021 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-20 · 2021 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-20 · 2021 — الدورة الثانية\nquestion: ما قناع الشبكة الأنسب إذا أردنا الحصول على عناوين IP تكفي لـ 305 جهاز حاسوب؟\n- [ ] option-1 | 255.255.255.0\n- [x] option-2 | 255.255.0.0\n- [ ] option-3 | 256.0.0.0\n- [ ] option-4 | 255.255.255.1\nexplanation:\nنقارن سعة كل قناع بالعدد المطلوب، وهو **305 أجهزة**:\n\n- **`255.255.255.0`:** يترك 8 بتات للجهاز، فيوفر $2^8=256$ عنوانًا، فلا يكفي.\n- **`255.255.0.0`:** يترك 16 بتًا، فيوفر $2^{16}=65536$ عنوانًا، فيكفي.\n\nإذن القناع **`255.255.0.0` هو الأنسب بين الخيارات المعطاة**. أما **256** فليست قيمة صحيحة لخانة IPv4، و**`255.255.255.1`** ليس قناعًا صحيحًا ذا بتات متصلة.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p047-q06\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-21 · 2021 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-21 · 2021 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-21 · 2021 — الدورة الثالثة\nquestion: ما الرقم المستخدم في قناع الشبكة، لتحديد الجزء الخاص بعنوان الشبكة؟\n- [ ] option-1 | 0\n- [ ] option-2 | 8\n- [x] option-3 | 255\n- [ ] option-4 | 256\nexplanation:\nيقول الكتاب:\n\n> يتم استخدام **الرقم 255** في قناع الشبكة لتحديد الجزء الخاص بعنوان الشبكة والرقم صفر (0) لتحديد الجزء الخاص بعنوان الجهاز.\n\nالكتاب، ص 13\n\nفي أقنعة الدرس ذات الخانات `255` و`0`: **255 للشبكة** و**0 للجهاز**.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::mcq\nid: it-e-p047-q07\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-22 · 2021 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-22 · 2021 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 1-22 · 2021 — الدورة الثالثة\nquestion: ماذا نحتاج للتنقل بين الشبكات؟\n- [ ] option-1 | نظام عنونة فيزيائي\n- [x] option-2 | نظام عنونة منطقي\n- [ ] option-3 | نظام عنونة مدمج\n- [ ] option-4 | عنوان MAC\nexplanation:\nيقول الكتاب:\n\n> ولكن للتنقل بين الشبكات نحن بحاجة لنظام عنونة آخر، يسمى **نظام العنونة المنطقي**، ومن أنظمة العنونة المنطقية الشائعة عنونة IP.\n\nالكتاب، ص 3\n\nالانتقال بين الشبكات يحتاج **عنونة منطقية مثل IP**؛ أما MAC فخاص بالوصلة المحلية.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n:::\n\n:::exam-question\nid: it-e-p047-q08\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-1 · 2019 — الدورة الأولى\nquestion: جهاز حاسوب موجود في مدينة الناصرة بعنوان (192.168.2.1) يريد إرسال رسالة لجهاز موجود في مدينة يافا بعنوان (192.168.3.2)، قناع الشبكة لكلا الجهازين (255.255.255.0) وضح كيف يمكن ربط الجهازين.\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-1 · 2019 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nجهاز حاسوب موجود في مدينة الناصرة بعنوان (192.168.2.1) يريد إرسال رسالة لجهاز موجود في مدينة يافا بعنوان (192.168.3.2)، قناع الشبكة لكلا الجهازين (255.255.255.0) وضح كيف يمكن ربط الجهازين.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nلأنهما ليسا على نفس الشبكة، يتم الربط بينهما عن طريق الموجه (Router).\nsolution:\nنحدد جزء الشبكة أولًا. القناع **`255.255.255.0`** يجعل أول ثلاث خانات للشبكة:\n\n- شبكة المصدر: **`192.168.2`**.\n- شبكة الهدف: **`192.168.3`**.\n\nالجزءان مختلفان، إذن الجهازان ليسا داخل الشبكة المحلية نفسها. نستخدم **موجهًا Router** متصلًا بالشبكتين لتمرير الحزم بينهما.\n:::\n\n:::exam-question\nid: it-e-p047-q09\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-2 · 2019 — الدورة الأولى\nquestion: لديك عنوان IP (192.168.18.1) لجهاز وقناع شبكة (255.255.255.0)، أجب عما يلي:\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-2 · 2019 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nلديك عنوان IP (192.168.18.1) لجهاز وقناع شبكة (255.255.255.0)، أجب عما يلي:\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n- أ. ما عنوان الجهاز؟\n- ب. كم عنوانًا موجود بالشبكة؟\n- ج. ما تنفيذ الأمر الآتي (في شاشة CMD): Tracert www.Alquds.com.\nfinal-answer:\n- أ. 1.\n- ب. 2⁸ = 256 عنوانًا.\n- ج. معرفة عدد الموجهات التي تقوم بتوجيه الرسالة وصولًا لموقع Alquds.com.\nsolution:\nنجيب عن الفروع بالترتيب:\n\n- **أ. جزء الجهاز:** القناع `255.255.255.0` يحدد أول ثلاث خانات للشبكة، ويترك الخانة الأخيرة للجهاز؛ فقيمتها **1**.\n- **ب. عدد العناوين:** تتبقى 8 بتات للجهاز، فيكون المجموع:\n\n$$2^8=256$$\n\n- **ج. وظيفة الأمر:** `tracert www.Alquds.com` يتتبع المسار إلى الوجهة ويعرض قفزاته، ولا يغيّر عنوان الجهاز.\n:::\n\n:::exam-question\nid: it-e-p047-q10\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-3 · 2019 — الدورة الثانية\nquestion: ما المقصود بكل من الآتية: قناع الشبكة (Subnet Mask).\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-3 · 2019 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما المقصود بكل من الآتية: قناع الشبكة (Subnet Mask).\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nقناع مكون من 4 خانات كعنوان IPv4 يستخدم من أجل التمييز بين عنوان الشبكة وعنوان الجهاز.\nsolution:\nيقول الكتاب:\n\n> قناع الشبكة subnet mask: حيث إن قناع الشبكة مكون من 4 خانات تماما كعنوان الـ IPv4، ويتم استخدام هذا القناع من أجل **التمييز بين الجزء الخاص بعنوان الجهاز والجزء الخاص بعنوان الشبكة**.\n\nالكتاب، ص 12\n:::\n\n:::exam-question\nid: it-e-p047-q11\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-4 · 2019 — الدورة الثانية\nquestion: اذكر دورين من الأدوار التي تقوم بها الطبقة الثالثة؟\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-4 · 2019 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nاذكر دورين من الأدوار التي تقوم بها الطبقة الثالثة؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n- التنقل بين الشبكات عن طريق العنوان المنطقي IP حيث لكل جهاز IP يميزه عن غيره.\n- توجيه الرسالة (الحزمة) من الجهاز المصدر للهدف عبر الموجهات (ROUTERS)، حيث يقوم بتوجيه الرسالة عبر أقصر الطرق حسب عنوان IP الهدف الموجود في رأس الحزمة.\nsolution:\nلطبقة الشبكة وظيفتان مترابطتان في الدرس:\n\n1. توفير **العنونة المنطقية IP** لتمييز الأجهزة وشبكاتها خارج حدود الوصلة المحلية.\n2. **توجيه الحزم** من المصدر إلى الهدف عبر الموجهات، باستخدام IP الهدف لاختيار اتجاه الإرسال.\n\nتعطي العنونة هوية الوجهة، ويستخدم التوجيه هذه الهوية لنقل الرسالة. الكتاب، ص 11.\n:::\n\n:::exam-question\nid: it-e-p047-q12\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-5 · 2019 — الدورة الثانية\nquestion: لدينا عنوان IP (192.168.25.1) لجهاز وقناع شبكة (255.255.0.0)، أجب عما يلي:\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-5 · 2019 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nلدينا عنوان IP (192.168.25.1) لجهاز وقناع شبكة (255.255.0.0)، أجب عما يلي:\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n- أ. ما عنوان الشبكة؟\n- ب. كم عنوانًا موجود بالشبكة؟\n- ج. ما تنفيذ الأمر الآتي (في شاشة CMD): Tracert www.tinkercad.com.\nfinal-answer:\n- أ. 192.168.\n- ب. 2¹⁶ = 65,536 عنوانًا.\n- ج. معرفة عدد الموجهات التي تقوم بتوجيه الرسالة وصولًا لموقع tinkercad.com.\nsolution:\nالقناع **`255.255.0.0`** يترك أول خانتين للشبكة وآخر خانتين للجهاز. نطبق ذلك على فروع السؤال:\n\n- **أ. جزء الشبكة:** **`192.168`**.\n- **ب. عدد العناوين:** يتبقى 16 بتًا للجهاز، لذلك:\n\n$$2^{16}=65536$$\n\n- **ج. وظيفة الأمر:** `tracert www.tinkercad.com` يعرض قفزات المسار إلى الموقع، فتُعرف منه الموجهات التي تمر بها الرسالة.\n:::\n\n:::exam-question\nid: it-e-p047-q13\ntitle: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-6 · 2019 — الدورة الثانية\nquestion: ما وظيفة بروتوكول إعدادات المضيف الديناميكية (DHCP)؟\nreference: مجموعة الامتحانات · ص 47 · PDF 47 · السؤال 2-6 · 2019 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما وظيفة بروتوكول إعدادات المضيف الديناميكية (DHCP)؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nيقوم بتوزيع عناوين IP تلقائيًا على أجهزة الشبكة التي تتطلب هذه الخدمة.\nsolution:\nيقوم **DHCP** بتوزيع عناوين IP تلقائيًا من مجموعة متاحة لديه على أجهزة الشبكة التي تطلب الخدمة، بدل تكوين عنوان كل جهاز يدويًا. لذلك يقابل وصف «توزيع العناوين تلقائيًا» هذا البروتوكول. الكتاب، ص 14.\n:::\n\n:::exam-question\nid: it-e-p048-q01\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-7 · 2019 — الدورة الثالثة\nquestion: قارن بين طبقة ربط البيانات وطبقة الشبكة من حيث نظام العنونة وتنسيق الرسالة؟\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-7 · 2019 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nقارن بين طبقة ربط البيانات وطبقة الشبكة من حيث نظام العنونة وتنسيق الرسالة؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n| من حيث | طبقة ربط البيانات | طبقة الشبكة |\n|---|---|---|\n| نظام العنونة | عنوان فيزيائي (MAC) | عنوان منطقي (IP) |\n| تنسيق الرسالة | إطار | حزمة |\nsolution:\nنقارن نطاق العمل أولًا، ثم نربطه بالعنوان وتنسيق الرسالة:\n\n| وجه المقارنة | طبقة ربط البيانات | طبقة الشبكة |\n|---|---|---|\n| نطاق العمل | داخل الوصلة المحلية | بين الشبكات |\n| العنوان المستخدم | MAC الفيزيائي | IP المنطقي |\n| تنسيق الرسالة | إطار Frame | حزمة Packet |\n\nاختلاف نطاق العمل يفسر اختلاف نوع العنوان وتنسيق الرسالة. الكتاب، ص 3–4 و11.\n:::\n\n:::exam-question\nid: it-e-p048-q02\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-8 · 2019 — الدورة الثالثة\nquestion: قارن بين MAC Address وIP Address من حيث: نظام العنونة، عدد الخانات الثنائية.\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-8 · 2019 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nقارن بين MAC Address وIP Address من حيث: نظام العنونة، عدد الخانات الثنائية.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n| من حيث | MAC Address | IP Address |\n|---|---|---|\n| نظام العنونة | فيزيائي | منطقي |\n| عدد الخانات الثنائية | 48 بت | 32 بت |\nsolution:\nنفرق بين **طول العنوان بالبتات** و**طريقة كتابته**:\n\n| العنوان | نوع العنونة | عدد البتات | طريقة العرض في الدرس |\n|---|---|---|---|\n| MAC | فيزيائي | 48 بت | النظام السادس عشر |\n| IPv4 | منطقي | 32 بت | أربع خانات عشرية، كل منها تمثل 8 بتات |\n\nتغيير طريقة الكتابة لا يغيّر عدد البتات التي يتكون منها العنوان. الكتاب، ص 4 و12.\n:::\n\n:::exam-question\nid: it-e-p048-q03\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-9 · 2020 — الدورة الأولى\nquestion: قارن بين طبقة ربط البيانات وطبقة الشبكة من حيث نظام العنونة وتنسيق الرسالة؟\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-9 · 2020 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nقارن بين طبقة ربط البيانات وطبقة الشبكة من حيث نظام العنونة وتنسيق الرسالة؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n| من حيث | طبقة ربط البيانات | طبقة الشبكة |\n|---|---|---|\n| نظام العنونة | عنوان فيزيائي (MAC) | عنوان منطقي (IP) |\n| تنسيق الرسالة | إطار | حزمة |\nsolution:\nنقارن نطاق العمل أولًا، ثم نربطه بالعنوان وتنسيق الرسالة:\n\n| وجه المقارنة | طبقة ربط البيانات | طبقة الشبكة |\n|---|---|---|\n| نطاق العمل | داخل الوصلة المحلية | بين الشبكات |\n| العنوان المستخدم | MAC الفيزيائي | IP المنطقي |\n| تنسيق الرسالة | إطار Frame | حزمة Packet |\n\nاختلاف نطاق العمل يفسر اختلاف نوع العنوان وتنسيق الرسالة. الكتاب، ص 3–4 و11.\n:::\n\n:::exam-question\nid: it-e-p048-q04\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-10 · 2020 — الدورة الأولى\nquestion: يحصل الجهاز على عنوان IP من خلال طريقتين، وكيف تختار بين الطريقتين حسب طبيعة عمل الجهاز؟\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-10 · 2020 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nيحصل الجهاز على عنوان IP من خلال طريقتين، وكيف تختار بين الطريقتين حسب طبيعة عمل الجهاز؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n- الطريقة التلقائية: إذا كانت طبيعة عمل الجهاز طلب الخدمة من الشبكة مثل تصفح الإنترنت.\n- أما الطريقة اليدوية: إذا كانت طبيعة عمل الجهاز توفير خدمة على الشبكة مثل طابعة شبكة.\nsolution:\nنختار طريقة العنوان وفق **وظيفة الجهاز**:\n\n- جهاز يطلب خدمة، مثل جهاز للتصفح: يناسبه **التوزيع التلقائي DHCP** ليحصل على إعداداته دون تكوين يدوي.\n- جهاز يقدم خدمة، مثل طابعة شبكة: يناسبه **عنوان ثابت بالتكوين اليدوي** حتى تجد الأجهزة الخدمة في العنوان نفسه.\n\nثبات العنوان هو سبب اختيار الطريقة الثانية للخادم، وليس مجرد كون الجهاز في مكان ثابت. الكتاب، ص 14.\n:::\n\n:::exam-question\nid: it-e-p048-q05\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-11 · 2020 — الدورة الأولى\nquestion: ما المهام التي يقوم بها بروتوكول PPP؟\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-11 · 2020 — الدورة الأولى\nanswer-label: إجابة نموذجية للتدريب\nbody:\nما المهام التي يقوم بها بروتوكول PPP؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n1. يغلّف حزم بروتوكولات الشبكة المختلفة لنقلها عبر وصلة بين نقطتين.\n2. ينشئ وصلة ربط البيانات ويضبطها ويختبرها وينهيها باستخدام LCP، ويمكنه التحقق من هوية الطرف الآخر عند طلب ذلك.\n3. يضبط بروتوكولات طبقة الشبكة التي ستمر عبر الوصلة باستخدام NCP، مثل بروتوكول IP.\nsolution:\nيجمع **PPP** ثلاث وظائف على وصلة بين نقطتين:\n\n1. **التغليف:** يضع حزم بروتوكولات الشبكة داخل إطار مناسب للوصلة.\n2. **LCP:** ينشئ وصلة ربط البيانات ويضبطها ويختبرها وينهيها؛ ويمكن إجراء تحقق من الهوية عند طلبه.\n3. **NCP:** يضبط بروتوكولات طبقة الشبكة التي تعمل فوق الوصلة، مثل IP.\n\nهذا جواب نموذجي موثق بالمواصفة؛ مفتاح المجموعة انتقل إلى سؤال آخر. [RFC 1661، الأقسام 1 و3 و4](https://www.rfc-editor.org/rfc/rfc1661.html).\n:::\n\n:::exam-question\nid: it-e-p048-q06\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-12 · 2020 — الدورة الثانية\nquestion: إذا علمت أن عنوان IP هو: 192.168.2.25 وقناع الشبكة هو: 255.255.0.0 أجب عما يلي:\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-12 · 2020 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nإذا علمت أن عنوان IP هو: 192.168.2.25 وقناع الشبكة هو: 255.255.0.0 أجب عما يلي:\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n- أ. ما هو عنوان الشبكة؟\n- ب. ما هو عنوان الجهاز داخل الشبكة؟\n- ج. كم عنوانًا موجودًا في هذه الشبكة؟\nfinal-answer:\n- أ. 192.168.\n- ب. 2.25.\n- ج. 2¹⁶ (65,536) عنوانًا.\nsolution:\nنقرأ القناع **`255.255.0.0`**: أول خانتين للشبكة، وآخر خانتين للجهاز. في العنوان **`192.168.2.25`** نحصل على:\n\n- **أ. جزء الشبكة:** **`192.168`**.\n- **ب. جزء الجهاز:** **`2.25`**.\n- **ج. مجموع العناوين:** آخر خانتين تضمان 16 بتًا، لذلك:\n\n$$2^{16}=65536$$\n\nإذا طُلب **عنوان الشبكة الكامل** بدل جزء الشبكة، نكتبه **`192.168.0.0/16`**.\n:::\n\n:::exam-question\nid: it-e-p048-q07\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-13 · 2020 — الدورة الثانية\nquestion: يود جهاز حاسوب في مدينة نابلس بعنوان 192.168.1.3 يريد إرسال رسالة لجهاز موجود في مدينة القدس بعنوان 192.168.3.3 علمًا بأن قناع الشبكة لكلا الجهازين 255.255.255.0.\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-13 · 2020 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nيود جهاز حاسوب في مدينة نابلس بعنوان 192.168.1.3 يريد إرسال رسالة لجهاز موجود في مدينة القدس بعنوان 192.168.3.3 علمًا بأن قناع الشبكة لكلا الجهازين 255.255.255.0.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n- أ. علل: نحتاج موجه لتوجيه الرسالة بين الجهازين.\n- ب. ما هو عنوان IP الهدف وعنوان IP المصدر في المرحلة الأولى؟\n- ج. ما هو عنوان MAC المصدر وعنوان MAC الهدف في المرحلة الثالثة؟\nfinal-answer:\n- أ. لأن الجهازين ليسا على نفس الشبكة.\n- ب.\n  - عنوان IP الهدف هو `192.168.3.3`.\n  - عنوان IP المصدر هو `192.168.1.3`.\n- ج.\n  - عنوان MAC المصدر عنوان MAC منفذ الموجه الثاني المتصل بجهاز حاسوب الهدف.\n  - عنوان MAC الهدف عنوان MAC الجهاز الثاني (حاسوب الهدف).\nsolution:\nنجيب عن كل فرع بحسب نوع العنوان:\n\n- **أ. الحاجة إلى موجه:** القناع `/24` يجعل شبكتي الجهازين `192.168.1` و`192.168.3`. اختلافهما يعني أن الرسالة تعبر بين شبكتين.\n- **ب. عنوانا IP:** المصدر **`192.168.1.3`** والهدف **`192.168.3.3`**. يبقيهما التوجيه العادي ثابتين طوال الرحلة.\n- **ج. عنوانا MAC في المرحلة الثالثة:** هي الوصلة الأخيرة؛ المصدر هو **منفذ الموجه الثاني المتصل بشبكة الهدف**، والهدف هو **جهاز القدس**.\n\nعنوانا MAC يحددان طرفي الوصلة الحالية، لذلك يختلفان عن عنواني IP اللذين يحددان طرفي الرحلة.\n:::\n\n:::exam-question\nid: it-e-p048-q08\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-14 · 2020 — الدورة الثالثة\nquestion: جهاز حاسوب في مدينة القدس عنوان (10.0.0.22)، يريد إرسال رسالة لجهاز في مدينة أريحا عنوانه (192.168.1.1) وقناع الشبكة لهما (255.255.255.0) هل الجهازين موجودان في الشبكة نفسها؟ وكيف يتم ربطهما معًا؟\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-14 · 2020 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nجهاز حاسوب في مدينة القدس عنوان (10.0.0.22)، يريد إرسال رسالة لجهاز في مدينة أريحا عنوانه (192.168.1.1) وقناع الشبكة لهما (255.255.255.0) هل الجهازين موجودان في الشبكة نفسها؟ وكيف يتم ربطهما معًا؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nالجهازان على شبكتين مختلفتين، بسبب الاختلاف في الجزء الخاص بعنوان الشبكة، نحتاج جهاز الموجه (Router) للربط بينهما.\nsolution:\nمع القناع **255.255.255.0** نقارن أول ثلاث خانات: **10.0.0** لا يساوي **192.168.1**. إذن الجهازان على شبكتين مختلفتين ويحتاجان **موجهًا Router** لنقل الحزم بينهما؛ اختلاف المدينة وحده ليس معيار الحكم.\n:::\n\n:::exam-question\nid: it-e-p048-q09\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-15 · 2020 — الدورة الثالثة\nquestion: ما أهمية قناع الشبكة Subnet mask؟\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-15 · 2020 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما أهمية قناع الشبكة Subnet mask؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nقناع مكون من 4 خانات كعنوان IPv4 يستخدم من أجل التمييز بين عنوان الشبكة وعنوان الجهاز.\nsolution:\nيقول الكتاب:\n\n> قناع الشبكة subnet mask: حيث إن قناع الشبكة مكون من 4 خانات تماما كعنوان الـ IPv4، ويتم استخدام هذا القناع من أجل **التمييز بين الجزء الخاص بعنوان الجهاز والجزء الخاص بعنوان الشبكة**.\n\nالكتاب، ص 12\n:::\n\n:::exam-question\nid: it-e-p048-q10\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-16 · 2020 — الدورة الثالثة\nquestion: ما نتيجة كتابة الأمر tracert www.moeh.edu.ps على موجه سطر الأوامر؟\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-16 · 2020 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما نتيجة كتابة الأمر tracert www.moeh.edu.ps على موجه سطر الأوامر؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nمعرفة عدد الموجهات التي تقوم بتوجيه الرسالة وصولًا لموقع www.moeh.edu.ps.\nsolution:\nالأمر **`tracert www.moeh.edu.ps`** يرسل فحوص تتبع إلى الوجهة ويعرض القفزات على المسار. لذلك نعرف من نتائجه مسار الموجهات التي تمر بها الرسالة وصولًا للموقع، خلاف `ping` الذي يفحص إمكانية الاتصال. الكتاب، ص 20.\n:::\n\n:::exam-question\nid: it-e-p048-q11\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-17 · 2020 — الدورة الثالثة\nquestion: ما نظام العنونة المستخدم في كل من طبقة الشبكة وطبقة ربط البيانات؟\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-17 · 2020 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما نظام العنونة المستخدم في كل من طبقة الشبكة وطبقة ربط البيانات؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n- نظام العنونة في طبقة ربط البيانات هو العنوان الفيزيائي.\n- أما في طبقة الشبكة فهو العنوان المنطقي.\nsolution:\n**طبقة ربط البيانات:** عنونة فيزيائية **MAC** داخل الوصلة المحلية.\n\n**طبقة الشبكة:** عنونة منطقية **IP** لتحديد الأجهزة وشبكاتها والتوجيه بينها. الكتاب، ص 3–4 و11.\n:::\n\n:::exam-question\nid: it-e-p048-q12\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-18 · 2021 — الدورة الأولى\nquestion: ما الفرق بين العنوان المنطقي والعنوان الفيزيائي؟\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-18 · 2021 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nما الفرق بين العنوان المنطقي والعنوان الفيزيائي؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n| وجه المقارنة | العنونة الفيزيائية | العنونة المنطقية |\n|---|---|---|\n| الوظيفة | نقل البيانات داخل شبكة الحاسوب المحلية | نقل البيانات بين الشبكات المختلفة |\n| الطبقة التي توجد بها | طبقة ربط البيانات | طبقة الشبكة |\n| مثال | عنوان MAC | عنوان IP |\nsolution:\nنرتب المقارنة حسب نطاق الوظيفة:\n\n| الوجه | العنونة الفيزيائية | العنونة المنطقية |\n|---|---|---|\n| الطبقة | ربط البيانات | الشبكة |\n| الوظيفة | النقل داخل الوصلة المحلية | التوجيه بين الشبكات |\n| العنوان | MAC | IP |\n\nالعنوان المنطقي يحدد الوجهة النهائية، بينما العنوان الفيزيائي يحدد طرف الوصلة الحالية. الكتاب، ص 21–22.\n:::\n\n:::exam-question\nid: it-e-p048-q13\ntitle: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-19 · 2021 — الدورة الأولى\nquestion: تأمل الشكل الآتي الخاص بإرسال رسالة من الجهاز PC1 إلى الجهاز PC2، ثم أجب عن الأسئلة التي تليه:\nreference: مجموعة الامتحانات · ص 48 · PDF 48 · السؤال 2-19 · 2021 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nتأمل الشكل الآتي الخاص بإرسال رسالة من الجهاز PC1 إلى الجهاز PC2، ثم أجب عن الأسئلة التي تليه:\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n![شبكتان وعناوين IP وMAC](assets/lessons/adabi/information-technology/assets/it-e-p048-q13-fig01.webp)\n\n- أ. اشرح كيف سيكون مسار الرسالة من الجهاز PC1 إلى واجهة الموجه المحلي؟\n- ب. إذا علمت أن قناع الشبكة للجهاز الأول (255.255.255.0)، فما عدد خانات الجزء الخاص بالشبكة، وما عدد خانات الجزء الخاص بعناوين الأجهزة.\nfinal-answer:\n- أ.\n  - عنوان IP المصدر هو `192.168.1.1`.\n  - عنوان IP الهدف `192.168.2.5`.\n  - عنوان MAC المصدر هو `BBCCDD:123456`.\n  - عنوان MAC الهدف هو `AABBCC:123456`.\n- ب.\n  - عدد الخانات الخاصة بالشبكة 3 خانات (24 بت).\n  - عدد الخانات الخاصة بالجهاز خانة (8 بت).\nsolution:\n1. في الوصلة الأولى تبقى وجهة الحزمة **PC2**؛ لذلك IP المصدر **192.168.1.1** والهدف **192.168.2.5**.\n2. الوجهة الفيزيائية المباشرة هي **واجهة الموجه المحلي**، لا PC2 الموجود بشبكة أخرى؛ لذلك MAC المصدر **BBCCDD:123456** وMAC الهدف **AABBCC:123456** كما يحدد الرسم.\n3. القناع **255.255.255.0** يحجز أول ثلاث خانات، أي **24 بتًا للشبكة**، وتبقى خانة واحدة، أي **8 بتات للجهاز**.\n:::\n\n:::exam-question\nid: it-e-p049-q01\ntitle: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-20 · 2021 — الدورة الأولى\nquestion: في الشكل الآتي يتم توجيه رسالة بين جهازين في شبكتين مختلفتين حيث الموجه على منفذين أحدهما ينتمي للشبكة الأولى والآخر ينتمي للشبكة الثانية. وضح كيف سيكون مسار الرسالة من الجهاز (1) إلى الجهاز (2) عبر الموجه مع تحديد عناوين IP وMAC في كل مرحلة.\nreference: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-20 · 2021 — الدورة الأولى\nanswer-label: إجابة المفتاح بعد التصحيح الموثق\nbody:\nفي الشكل الآتي يتم توجيه رسالة بين جهازين في شبكتين مختلفتين حيث الموجه على منفذين أحدهما ينتمي للشبكة الأولى والآخر ينتمي للشبكة الثانية. وضح كيف سيكون مسار الرسالة من الجهاز (1) إلى الجهاز (2) عبر الموجه مع تحديد عناوين IP وMAC في كل مرحلة.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n![مسار رسالة بين جهازين وعناوين المنافذ](assets/lessons/adabi/information-technology/assets/it-e-p049-q01-fig01.webp)\nfinal-answer:\n| المرحلة | IP المصدر | IP الهدف | MAC المصدر | MAC الهدف |\n|---|---|---|---|---|\n| الأولى | 192.168.6.6 | 192.168.4.2 | 8CDCD4.4337EF | 4F2ED4.45D32D |\n| الثالثة | 192.168.6.6 | 192.168.4.2 | FF2CD4.4ED32F | FCDE12.4837ED |\n\nفي المرحلة الثانية يتفحص الموجه عنوان IP الهدف ويوجه الرسالة إلى المنفذ الثاني.\nsolution:\nنطبق قاعدة الكتاب: **عناوين IP لطرفي الرحلة، وعناوين MAC لطرفي الوصلة الحالية**.\n\n- الوصلة الأولى: IP المصدر **192.168.6.6** والهدف **192.168.4.2**. MAC المصدر **8CDCD4.4337EF** وMAC الهدف **4F2ED4.45D32D**، وهو منفذ الموجه القريب من المصدر.\n- داخل الموجه: يفحص IP الهدف ويختار المنفذ المتصل بشبكته.\n- الوصلة الثالثة: يبقى عنوانا IP كما هما؛ MAC المصدر يصبح **FF2CD4.4ED32F** لمنفذ الخروج، وMAC الهدف **FCDE12.4837ED** للجهاز النهائي.\n\nعنوان المصدر الصحيح في الرسم **192.168.6.6**؛ كتابة 192.186.6.6 في المفتاح خطأ مصحح في الإصدار. الكتاب، ص 22–25.\n:::\n\n:::exam-question\nid: it-e-p049-q02\ntitle: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-21 · 2021 — الدورة الثانية\nquestion: قارن بين نظامي العنونة المنطقي (IPv4) والفيزيائي (MAC) وفقًا للمعايير: عدد الثنائيات المكونة له، النظام العددي المستخدم لتمثيله.\nreference: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-21 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح بعد التصحيح الموثق\nbody:\nقارن بين نظامي العنونة المنطقي (IPv4) والفيزيائي (MAC) وفقًا للمعايير: عدد الثنائيات المكونة له، النظام العددي المستخدم لتمثيله.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n| المعيار | المنطقي (IPv4) | الفيزيائي (MAC) |\n|---|---|---|\n| عدد الثنائيات | 32 بت | 48 بت |\n| النظام العددي | العشري | السادس عشر |\nsolution:\nنفرق بين **طول العنوان بالبتات** و**طريقة كتابته**:\n\n| العنوان | نوع العنونة | عدد البتات | طريقة العرض في الدرس |\n|---|---|---|---|\n| MAC | فيزيائي | 48 بت | النظام السادس عشر |\n| IPv4 | منطقي | 32 بت | أربع خانات عشرية، كل منها تمثل 8 بتات |\n\nتغيير طريقة الكتابة لا يغيّر عدد البتات التي يتكون منها العنوان. الكتاب، ص 4 و12.\n:::\n\n:::exam-question\nid: it-e-p049-q03\ntitle: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-22 · 2021 — الدورة الثانية\nquestion: ما هو عنوان IP؟ وكيف يحصل عليه؟\nreference: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-22 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما هو عنوان IP؟ وكيف يحصل عليه؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nهو عنوان فريد لكل جهاز على شبكة الاتصال يستخدم من قبل أجهزة الشبكات الأخرى للوصول للجهاز. ويتم الحصول عليه بطريقتين:\n\n- الطريقة التلقائية: إذا كانت طبيعة عمل الجهاز طلب الخدمة من الشبكة مثل تصفح الإنترنت.\n- أما الطريقة اليدوية: إذا كانت طبيعة عمل الجهاز توفير خدمة على الشبكة مثل طابعة شبكة.\nsolution:\n**IP** عنوان منطقي يميز الجهاز على شبكة الاتصال ويتيح توجيه الحزم إليه.\n\nفي أمثلة الدرس نختار طريقة الحصول عليه وفق وظيفة الجهاز:\n\n- **التلقائية عبر DHCP:** لجهاز يطلب الخدمات، مثل التصفح.\n- **اليدوية الثابتة:** لجهاز يقدم خدمة تحتاج عنوانًا معلومًا، مثل طابعة الشبكة.\n\nالكتاب، ص 11 و14.\n:::\n\n:::exam-question\nid: it-e-p049-q04\ntitle: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-23 · 2021 — الدورة الثانية\nquestion: أراد محمد أن يرسل رسالة إلى خالد عبر الشبكة، فإذا علمت أن قناع الشبكة لكلا الجهازين الخاصين بهما هو (255.255.255.0) أجب عن الأسئلة الآتية:\nreference: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-23 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nأراد محمد أن يرسل رسالة إلى خالد عبر الشبكة، فإذا علمت أن قناع الشبكة لكلا الجهازين الخاصين بهما هو (255.255.255.0) أجب عن الأسئلة الآتية:\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n![مخطط شبكة محمد وخالد](assets/lessons/adabi/information-technology/assets/it-e-p049-q04-fig01.webp)\n\n- أ. ما اسم الجهاز الذي يربط بين جهاز محمد وخالد؟\n- ب. كم عنوانًا موجودًا في الشبكة التي ينتمي إليها جهاز خالد؟\n- ج. ما هو عنوان الشبكة التي ينتمي لها جهاز محمد؟\n- د. هل جهاز محمد وخالد على نفس الشبكة، مع التوضيح؟\nfinal-answer:\n- أ. Router أو موجه.\n- ب. 2⁸ = 256 بحسب عدّ العناوين المعتمد في الكتاب.\n- ج. 192.168.3.\n- د. لا، لأن عنوان شبكة محمد 192.168.3 يختلف عن عنوان شبكة خالد 192.168.4.\nsolution:\nالقناع **`255.255.255.0`** يجعل أول ثلاث خانات للشبكة. نقرأ الرسم ثم نجيب بالترتيب:\n\n- **أ. جهاز الربط:** **Router (الموجه)**؛ لأنه يصل بين الشبكتين.\n- **ب. عدد عناوين شبكة خالد:** تتبقى 8 بتات لجزء الجهاز، فيكون المجموع:\n\n$$2^8=256$$\n\n- **ج. جزء شبكة محمد:** **`192.168.3`**.\n- **د. هل هما في الشبكة نفسها؟** لا؛ جزء شبكة محمد `192.168.3` يختلف عن جزء شبكة خالد `192.168.4`.\n\nالعدد هنا هو مجموع العناوين وفق عدّ الكتاب، ولا يقصد به عدد عناوين المضيفين القابلة للتخصيص بعد الحجز.\n:::\n\n:::exam-question\nid: it-e-p049-q05\ntitle: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-24 · 2021 — الدورة الثانية\nquestion: قارن بين الأمرين (ipconfig) و(ipconfig/all).\nreference: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-24 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nقارن بين الأمرين (ipconfig) و(ipconfig/all).\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n- Ipconfig: لتحديد عنوان IP لجهاز الحاسوب.\n- Ipconfig/all: لتحديد عنوان MAC على الجهاز.\nsolution:\nالفرق هو **مقدار التفاصيل التي يعرضها الأمر**:\n\n- **`ipconfig`:** يعرض إعدادات IP الأساسية، ومنها IPv4 وقناع الشبكة والبوابة الافتراضية.\n- **`ipconfig /all`:** يعرض تفاصيل أوسع عن محولات الشبكة، ومنها **Physical Address (MAC)**.\n\nإضافة `/all` توسّع المعلومات المعروضة، ولا تحوّل IP إلى MAC. الكتاب، ص 19.\n:::\n\n:::exam-question\nid: it-e-p049-q06\ntitle: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-25 · 2021 — الدورة الثانية\nquestion: لديك عنوان IP (155.133.14.11) لجهاز وقناع الشبكة (255.255.0.0) أجب عما يلي:\nreference: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-25 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nلديك عنوان IP (155.133.14.11) لجهاز وقناع الشبكة (255.255.0.0) أجب عما يلي:\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n- أ. ما عنوان الشبكة؟\n- ب. ما عنوان الجهاز؟\n- ج. كم عنوانًا في الشبكة؟\n- د. اكتب عنوان جهاز آخر على نفس الشبكة.\nfinal-answer:\n- أ. 155.133.\n- ب. 14.11.\n- ج. 2¹⁶ = 65,536 عنوانًا.\n- د. 155.133.100.15.\nsolution:\nالقناع **`255.255.0.0`** يخصص أول خانتين للشبكة وآخر خانتين للجهاز. نطبقه على **`155.133.14.11`**:\n\n- **أ. جزء الشبكة:** **`155.133`**.\n- **ب. جزء الجهاز:** **`14.11`**.\n- **ج. مجموع العناوين:** يوجد 16 بتًا للجهاز، لذلك:\n\n$$2^{16}=65536$$\n\n- **د. جهاز آخر في الشبكة نفسها:** نحافظ على `155.133` ونغيّر جزء الجهاز، مثل **`155.133.100.15`**، بشرط أن يكون غير مستخدم.\n:::\n\n:::exam-question\nid: it-e-p049-q07\ntitle: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-26 · 2021 — الدورة الثانية\nquestion: ما وظيفة كلٍّ مما يأتي: قناع الشبكة Subnet Mask.\nreference: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-26 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما وظيفة كلٍّ مما يأتي: قناع الشبكة Subnet Mask.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nقناع مكون من 4 خانات كعنوان IPv4 يستخدم من أجل التمييز بين عنوان الشبكة وعنوان الجهاز.\nsolution:\nيقول الكتاب:\n\n> قناع الشبكة subnet mask: حيث إن قناع الشبكة مكون من 4 خانات تماما كعنوان الـ IPv4، ويتم استخدام هذا القناع من أجل **التمييز بين الجزء الخاص بعنوان الجهاز والجزء الخاص بعنوان الشبكة**.\n\nالكتاب، ص 12\n:::\n\n:::exam-question\nid: it-e-p049-q08\ntitle: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-27 · 2021 — الدورة الثالثة\nquestion: ما وظيفة كلا من: أ. الأمر Ping. ب. قناع الشبكة.\nreference: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-27 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما وظيفة كلا من: أ. الأمر Ping. ب. قناع الشبكة.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n- أ. لفحص الاتصال مع عنوان IP على الشبكة.\n- ب. للتمييز بين الجزء الخاص بعنوان الجهاز والجزء الخاص بعنوان الشبكة.\nsolution:\n**ping:** يفحص إمكان الاتصال بعنوان IP ويظهر ردود الفحص أو غيابها.\n\n**قناع الشبكة:** يميز بتات الشبكة من بتات الجهاز في عنوان IP. الأول أداة تشخيص اتصال، والثاني جزء من إعدادات العنونة. الكتاب، ص 12 و19.\n:::\n\n:::exam-question\nid: it-e-p049-q09\ntitle: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-28 · 2021 — الدورة الثالثة\nquestion: لديك جهاز حاسوب في مدينة (القدس) بعنوان (192.168.6.1) يود إرسال رسالة إلى جهاز آخر في مدينة (غزة) بعنوان (192.168.8.2) علمًا بأن قناع الشبكة للجهازين هو (255.255.255.0).\nreference: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-28 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nلديك جهاز حاسوب في مدينة (القدس) بعنوان (192.168.6.1) يود إرسال رسالة إلى جهاز آخر في مدينة (غزة) بعنوان (192.168.8.2) علمًا بأن قناع الشبكة للجهازين هو (255.255.255.0).\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n- أ. هل الجهازين موجودان على نفس الشبكة؟\n- ب. ما عنوان IP للجهاز الهدف؟\n- ج. وضح كيف يمكن إرسال الرسالة بين الجهازين؟\nfinal-answer:\n- أ. لا.\n- ب. 192.168.8.2.\n- ج. لأنهما ليسا على نفس الشبكة، يتم الربط بينهما عن طريق الموجه (Router) حيث يرسل جهاز المصدر إلى الموجه المرتبط به، ثم يقوم الموجه بإرسال الرسالة لموجه الهدف، ومن موجه الهدف يتم إرسالها لجهاز الهدف.\nsolution:\nنحدد جزء الشبكة باستخدام القناع **`255.255.255.0`**، ثم نجيب عن الفروع:\n\n- **أ. هل الجهازان في الشبكة نفسها؟** لا؛ جزء شبكة القدس `192.168.6` يختلف عن جزء شبكة غزة `192.168.8`.\n- **ب. IP الهدف:** **`192.168.8.2`**، وهو عنوان جهاز غزة المطلوب الوصول إليه.\n- **ج. مسار الإرسال:** يرسل المصدر الإطار إلى موجه شبكته، ثم تنقله الموجهات نحو شبكة غزة، ومنها إلى الجهاز.\n\nيبقى IP الهدف نفسه، بينما تتبدل عناوين MAC بحسب الوصلة الحالية.\n:::\n\n:::exam-question\nid: it-e-p049-q10\ntitle: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-29 · 2021 — الدورة الثالثة\nquestion: ما المقصود بكلا من: الموجه Router.\nreference: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-29 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما المقصود بكلا من: الموجه Router.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nجهاز يتصل بشبكة الإنترنت من خلال خط المشترك الرقمي الذي توفره شركة الاتصال، وهو من أكثر الأجهزة شيوعًا ويشكل النقطة الرئيسية في الشبكة المنزلية.\nsolution:\n**الموجّه Router** يربط شبكات مختلفة ويوجّه الحزم بينها اعتمادًا على IP الهدف. تصف إجابة مجموعة الامتحان مثال الموجّه المنزلي المتصل بخط المشترك الرقمي؛ هذه حالة تطبيقية وليست شرطًا لتعريف جميع الموجهات. الكتاب، ص 20–21.\n:::\n\n:::exam-question\nid: it-e-p049-q11\ntitle: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-30 · 2021 — الدورة الثالثة\nquestion: ما المقصود ببروتوكول إعدادات المضيف الديناميكية (DHCP)؟\nreference: مجموعة الامتحانات · ص 49 · PDF 49 · السؤال 2-30 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما المقصود ببروتوكول إعدادات المضيف الديناميكية (DHCP)؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nهو بروتوكول يقوم بتوزيع عناوين IP تلقائيًا على أجهزة الشبكة التي تتطلب هذه الخدمة.\nsolution:\nيقوم **DHCP** بتوزيع عناوين IP تلقائيًا من مجموعة متاحة لديه على أجهزة الشبكة التي تطلب الخدمة، بدل تكوين عنوان كل جهاز يدويًا. لذلك يقابل وصف «توزيع العناوين تلقائيًا» هذا البروتوكول. الكتاب، ص 14.\n:::\n\n:::exam-question\nid: it-e-p050-q01\ntitle: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-31 · 2021 — الدورة الثالثة\nquestion: في الشكل الآتي يتم توجيه رسالة بين جهازين في شبكتين مختلفتين حيث الموجه على منفذين أحدهما ينتمي للشبكة الأولى والآخر ينتمي للشبكة الثانية. وضح كيف سيكون مسار الرسالة من الجهاز (1) إلى الجهاز (2) عبر الموجه مع تحديد عناوين IP وMAC في كل مرحلة.\nreference: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-31 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح بعد التصحيح الموثق\nbody:\nفي الشكل الآتي يتم توجيه رسالة بين جهازين في شبكتين مختلفتين حيث الموجه على منفذين أحدهما ينتمي للشبكة الأولى والآخر ينتمي للشبكة الثانية. وضح كيف سيكون مسار الرسالة من الجهاز (1) إلى الجهاز (2) عبر الموجه مع تحديد عناوين IP وMAC في كل مرحلة.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n![مخطط توجيه الرسالة مع عناوين الجهازين والموجه](assets/lessons/adabi/information-technology/assets/it-e-p050-q01-fig01.webp)\nfinal-answer:\n| المرحلة | IP المصدر | IP الهدف | MAC المصدر | MAC الهدف |\n|---|---|---|---|---|\n| الأولى | 192.168.6.6 | 192.168.4.2 | 8CDCD4.4337EF | 4F2ED4.45D32D |\n| الثالثة | 192.168.6.6 | 192.168.4.2 | FF2CD4.4ED32F | FCDE12.4837ED |\n\nفي المرحلة الثانية يتفحص الموجه عنوان IP الهدف ويوجه الرسالة إلى المنفذ الثاني.\nsolution:\nنطبق قاعدة الكتاب: **عناوين IP لطرفي الرحلة، وعناوين MAC لطرفي الوصلة الحالية**.\n\n- الوصلة الأولى: IP المصدر **192.168.6.6** والهدف **192.168.4.2**. MAC المصدر **8CDCD4.4337EF** وMAC الهدف **4F2ED4.45D32D**، وهو منفذ الموجه القريب من المصدر.\n- داخل الموجه: يفحص IP الهدف ويختار المنفذ المتصل بشبكته.\n- الوصلة الثالثة: يبقى عنوانا IP كما هما؛ MAC المصدر يصبح **FF2CD4.4ED32F** لمنفذ الخروج، وMAC الهدف **FCDE12.4837ED** للجهاز النهائي.\n\nعنوان المصدر الصحيح في الرسم **192.168.6.6**؛ كتابة 192.186.6.6 في المفتاح خطأ مصحح في الإصدار. الكتاب، ص 22–25.\n:::\n\n:::exam-question\nid: it-e-p050-q02\ntitle: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-32 · 2021 — الدورة الثالثة\nquestion: يحصل الجهاز على عنوان IP من خلال طريقتين، اذكرهما ووضح كيف تختار بين الطريقتين.\nreference: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-32 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح بعد التصحيح الموثق\nbody:\nيحصل الجهاز على عنوان IP من خلال طريقتين، اذكرهما ووضح كيف تختار بين الطريقتين.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n![مخرجات موجه الأوامر وحقلا قناع الشبكة والبوابة](assets/lessons/adabi/information-technology/assets/it-e-p050-q02-fig01.webp)\n\n- أ. ما عنوان IP للجهاز؟\n- ب. على ماذا يدل السطر المشار إليه بالرقم (1)؟\n- ج. ما وظيفة ما يشير إليه الرقم (2)؟\n- د. ما الأمر الذي أظهر النافذة أعلاه من خلال موجه الأوامر (CMD)؟\nfinal-answer:\n- الطريقة التلقائية: إذا كانت طبيعة عمل الجهاز طلب الخدمة من الشبكة مثل تصفح الإنترنت.\n- أما الطريقة اليدوية: إذا كانت طبيعة عمل الجهاز توفير خدمة على الشبكة مثل طابعة شبكة.\n\n- أ. عنوان IP للجهاز: 192.168.0.100.\n- ب. قناع الشبكة.\n- ج. البوابة الافتراضية (الموجه) Router التي تتيح للجهاز الخروج من الشبكة الداخلية والوصول لشبكة الإنترنت.\n- د. Ipconfig.\nsolution:\nنقرأ كل سطر وفق اسمه في نافذة الأوامر:\n\n- **IPv4 Address:** عنوان الجهاز **192.168.0.100**، وليس 192.168.0.50 الوارد خطأ في المفتاح.\n- **Subnet Mask** المشار إليه بـ(1): يميز جزء الشبكة من جزء الجهاز.\n- **Default Gateway** المشار إليه بـ(2): عنوان الموجّه الذي تستخدمه الحزم للخروج من الشبكة المحلية.\n- النافذة تظهر باستعمال **`ipconfig`**.\n\nأما طريقتا تعيين IP فهما التلقائية عبر DHCP لجهاز يطلب الخدمة، واليدوية الثابتة لجهاز يقدم خدمة. ثبات عنوان الخادم يساعد الأجهزة الأخرى على الوصول إليه. الكتاب، ص 14 و19.\n:::\n\n:::exam-question\nid: it-e-p050-q03\ntitle: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-33 · 2022 — الدورة الأولى\nquestion: قارن بين الطبقتين الثانية (طبقة ربط البيانات) والثالثة (طبقة الشبكة) بنموذج OSI من حيث: الوظيفة، وتنسيق الرسالة؟\nreference: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-33 · 2022 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nقارن بين الطبقتين الثانية (طبقة ربط البيانات) والثالثة (طبقة الشبكة) بنموذج OSI من حيث: الوظيفة، وتنسيق الرسالة؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n| وجه المقارنة | ربط البيانات | طبقة الشبكة |\n|---|---|---|\n| الوظيفة | تنظيم نقل البيانات في الشبكة المحلية | تنظيم نقل البيانات في الشبكة العالمية |\n| تنسيق الرسالة | إطار | حزمة |\nsolution:\nنحدد أولًا نطاق كل طبقة، ثم تنسيق الرسالة:\n\n- **ربط البيانات:** تنظم مرور البيانات داخل الشبكة المحلية، وتتعامل مع **إطار Frame**.\n- **الشبكة:** توجه البيانات بين الشبكات عبر الموجهات، وتتعامل مع **حزمة Packet**.\n\nالحزمة تحمل الوجهة المنطقية، ثم تُنقل على الوصلة داخل إطار مناسب. الكتاب، ص 3 و11.\n:::\n\n:::exam-question\nid: it-e-p050-q04\ntitle: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-34 · 2022 — الدورة الأولى\nquestion: أجب عما يأتي: وضح المرحلة الأولى لإرسال الرسالة من الجهاز رقم 1 إلى الجهاز رقم 2، مستعينًا بالشكل أدناه:\nreference: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-34 · 2022 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nأجب عما يأتي: وضح المرحلة الأولى لإرسال الرسالة من الجهاز رقم 1 إلى الجهاز رقم 2، مستعينًا بالشكل أدناه:\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n![المرحلة الأولى لإرسال الرسالة بين شبكتين](assets/lessons/adabi/information-technology/assets/it-e-p050-q04-fig01.webp)\nfinal-answer:\n| IP المصدر | IP الهدف | MAC المصدر | MAC الهدف |\n|---|---|---|---|\n| 192.168.1.11 | 192.168.2.22 | 0800.0100.1111 | 0800.0200.2222 |\nsolution:\nالمرحلة الأولى تصل جهاز المصدر **بواجهة الموجه في شبكته**. نميز بين وجهة الحزمة ووجهة الإطار:\n\n| نوع العنوان | المصدر | الهدف |\n|---|---|---|\n| IP | `192.168.1.11` | `192.168.2.22`، الجهاز النهائي |\n| MAC | `0800.0100.1111` | `0800.0200.2222`، واجهة الموجه المحلية |\n\nلا نضع MAC الجهاز النهائي في إطار هذه الوصلة الأولى؛ لأنه موجود في شبكة أخرى.\n:::\n\n:::exam-question\nid: it-e-p050-q05\ntitle: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-35 · 2022 — الدورة الأولى\nquestion: يريد جهاز حاسوب رقم (1) الموجود في مدينة أريحا بعنوان 192.168.10.56 إرسال رسالة إلى الجهاز رقم (2) الموجود في مدينة غزة، بعنوان 192.168.11.94 علمًا بأن قناع الشبكة لكلا الجهازين هو 255.255.255.0.\nreference: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-35 · 2022 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nيريد جهاز حاسوب رقم (1) الموجود في مدينة أريحا بعنوان 192.168.10.56 إرسال رسالة إلى الجهاز رقم (2) الموجود في مدينة غزة، بعنوان 192.168.11.94 علمًا بأن قناع الشبكة لكلا الجهازين هو 255.255.255.0.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\n\n- أ. لماذا نحتاج لجهاز الموجه Router بين الجهازين؟\n- ب. ما عنوان IP الهدف وعنوان IP المصدر في المرحلة الثالثة؟\nfinal-answer:\n- أ. لأن الجهازين ليسا على شبكة واحدة.\n- ب.\n  - عنوان IP الهدف `192.168.11.94`.\n  - عنوان IP المصدر `192.168.10.56`.\nsolution:\n- **أ. سبب الحاجة إلى موجه:** القناع `/24` يجعل جزء شبكة المصدر `192.168.10` وجزء شبكة الهدف `192.168.11`. اختلافهما يعني أن الرسالة تحتاج المرور بين شبكتين.\n- **ب. عنوانا IP في المرحلة الثالثة:** الهدف **`192.168.11.94`**، والمصدر **`192.168.10.56`**.\n\nيبقي التوجيه العادي هذين العنوانين ثابتين؛ الذي يتغير بين الوصلات هو عنوانا MAC.\n:::\n\n:::exam-question\nid: it-e-p050-q06\ntitle: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-36 · 2022 — الدورة الأولى\nquestion: قارن بين الطريقة اليدوية والطريقة التلقائية لتوزيع العنوان المنطقي IP على الأجهزة حسب طبيعة عمل الجهاز.\nreference: مجموعة الامتحانات · ص 50 · PDF 50 · السؤال 2-36 · 2022 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nقارن بين الطريقة اليدوية والطريقة التلقائية لتوزيع العنوان المنطقي IP على الأجهزة حسب طبيعة عمل الجهاز.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n- أ. الطريقة اليدوية: يتم تثبيت عنوان IP على الجهاز ويستخدم للأجهزة الثابتة مثل الطابعة.\n- ب. الطريقة التلقائية: خدمة DHCP في الموجه ويستخدم للأجهزة المتنقلة مثل اللابتوب.\nsolution:\nنختار طريقة العنوان وفق **وظيفة الجهاز**:\n\n- جهاز يطلب خدمة، مثل جهاز للتصفح: يناسبه **التوزيع التلقائي DHCP** ليحصل على إعداداته دون تكوين يدوي.\n- جهاز يقدم خدمة، مثل طابعة شبكة: يناسبه **عنوان ثابت بالتكوين اليدوي** حتى تجد الأجهزة الخدمة في العنوان نفسه.\n\nثبات العنوان هو سبب اختيار الطريقة الثانية للخادم، وليس مجرد كون الجهاز في مكان ثابت. الكتاب، ص 14.\n:::\n\n:::exam-question\nid: it-e-p051-q01\ntitle: مجموعة الامتحانات · ص 51 · PDF 51 · السؤال 2-37 · 2022 — الدورة الثانية\nquestion: ما وظيفة كل من: طبقة الشبكة.\nreference: مجموعة الامتحانات · ص 51 · PDF 51 · السؤال 2-37 · 2022 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما وظيفة كل من: طبقة الشبكة.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\nتنظيم نقل البيانات عبر الموجهات في الشبكة العالمية.\nsolution:\nيقول الكتاب:\n\n> من المهام الأخرى لهذه الطبقة **توجيه الرسالة (الحزمة) من المصدر للهدف عبر الموجهات** Routers، حيث يقوم الموجه بتوجيه الرسالة عبر أقصر الطرق اعتمادًا على عنوان IP الهدف الموجود في رأس الحزمة.\n\nالكتاب، ص 11\n:::\n\n:::exam-question\nid: it-e-p051-q02\ntitle: مجموعة الامتحانات · ص 51 · PDF 51 · السؤال 2-38 · 2022 — الدورة الثانية\nquestion: أجب عما يلي: كم عنوانًا موجودًا في شبكة قناعها (255.255.0.0)؟\nreference: مجموعة الامتحانات · ص 51 · PDF 51 · السؤال 2-38 · 2022 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nأجب عما يلي: كم عنوانًا موجودًا في شبكة قناعها (255.255.0.0)؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n2¹⁶.\nsolution:\nالقناع **`255.255.0.0`** يخصص أول خانتين للشبكة، ويترك آخر خانتين للجهاز. كل خانة تضم 8 بتات، إذن:\n\n$$2 \\times 8 = 16$$\n\nلكل بت احتمالان، فيكون مجموع العناوين:\n\n$$2^{16}=65536$$\n\nإذن العدد **65,536 عنوانًا** وفق عدّ العناوين في الكتاب. المطلوب مجموع العناوين، وليس عدد عناوين المضيفين القابلة للتخصيص بعد حجز عنواني الشبكة والبث.\n:::\n\n:::exam-question\nid: it-e-p051-q03\ntitle: مجموعة الامتحانات · ص 51 · PDF 51 · السؤال 2-39 · 2022 — الدورة الثانية\nquestion: قارن بين العنونة المنطقية والفيزيائية من حيث: الطبقة والوظيفة والعنوان المستخدم.\nreference: مجموعة الامتحانات · ص 51 · PDF 51 · السؤال 2-39 · 2022 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nقارن بين العنونة المنطقية والفيزيائية من حيث: الطبقة والوظيفة والعنوان المستخدم.\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n| وجه المقارنة | العنونة الفيزيائية | العنونة المنطقية |\n|---|---|---|\n| الوظيفة | نقل البيانات داخل شبكة الحاسوب المحلية | نقل البيانات بين الشبكات المختلفة |\n| الطبقة التي توجد بها | طبقة ربط البيانات | طبقة الشبكة |\n| مثال | عنوان MAC | عنوان IP |\nsolution:\nنرتب المقارنة حسب نطاق الوظيفة:\n\n| الوجه | العنونة الفيزيائية | العنونة المنطقية |\n|---|---|---|\n| الطبقة | ربط البيانات | الشبكة |\n| الوظيفة | النقل داخل الوصلة المحلية | التوجيه بين الشبكات |\n| العنوان | MAC | IP |\n\nالعنوان المنطقي يحدد الوجهة النهائية، بينما العنوان الفيزيائي يحدد طرف الوصلة الحالية. الكتاب، ص 21–22.\n:::\n\n:::exam-question\nid: it-e-p051-q04\ntitle: مجموعة الامتحانات · ص 51 · PDF 51 · السؤال 2-40 · 2022 — الدورة الثانية\nquestion: ما قناع الشبكة لجهازين عنوان IP الأول 192.168.8.5 وعنوان IP الثاني 192.168.1.8، إذا علمت أن الجهازين ينتميان لنفس الشبكة؟\nreference: مجموعة الامتحانات · ص 51 · PDF 51 · السؤال 2-40 · 2022 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما قناع الشبكة لجهازين عنوان IP الأول 192.168.8.5 وعنوان IP الثاني 192.168.1.8، إذا علمت أن الجهازين ينتميان لنفس الشبكة؟\n\n### الدرس الثاني — الطبقة الثالثة: طبقة الشبكة\nfinal-answer:\n255.255.0.0.\nsolution:\nنقارن الخانات بالترتيب:\n\n- العنوانان `192.168.8.5` و`192.168.1.8` يشتركان في **أول خانتين: `192.168`**.\n- يختلفان في الخانة الثالثة، لذلك لا يجعلهما القناع `/24` ضمن الشبكة نفسها.\n- القناع **`255.255.0.0`** يجعل أول خانتين للشبكة وآخر خانتين للجهاز، فيحقق المطلوب.\n\n**`/16` هو الجواب المعتمد في المجموعة**. معرفة أن الجهازين في شبكة واحدة لا تثبت وحدها أنه القناع الممكن الوحيد.\n:::";

